	return "\n".join(lines)

_AT = re.compile(r"(?=@)")

def lex(source: str) -> list[str]:
	#source = _strip_comments(source)
	raw = re.split(_AT, source)
	chunks = []
	for chunk in raw:
		chunk = chunk.strip()
		# remove all unnecessary
		if not chunk or not chunk.startswith("@"):
			continue
		chunk = _strip_blank_lines(chunk)
		if chunk:
